fn line_col(&self, span: Span) -> String {
    if span.is_dummy() {
        return "".into();
    }
    let loc = self.cm.lookup_char_pos(span.lo);
    let hic = self.cm.lookup_char_pos(span.hi);
    format!("({}:{}-{:?})", loc.line, loc.col_display + 1, hic.col_display + 1)
}
